-- ── Hand-written: what drizzle-kit cannot express ───────────────────────────
-- Search reads title, excerpt and search_text; there case and accents
-- (Arabic harakat, Polish ogonki) should not matter. uca1400 needs 10.10+.
ALTER TABLE `posts`
  MODIFY `title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci NOT NULL,
  MODIFY `excerpt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci,
  MODIFY `search_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci;
--> statement-breakpoint
-- Replaces the Postgres search_tsv column + GIN index (lib/search.ts).
CREATE FULLTEXT INDEX `posts_search_ft` ON `posts` (`title`, `excerpt`, `search_text`);
--> statement-breakpoint
-- A comment belongs to exactly one of a post or a page (was 0001 in Postgres).
ALTER TABLE `comments` ADD CONSTRAINT `comments_one_target`
  CHECK ((`post_id` IS NULL) <> (`page_id` IS NULL));
